def reorder_list(values):
    arr = list(values)
    out = []
    left, right = 0, len(arr) - 1
    while left <= right:
        if left == right:
            out.append(arr[left])
        else:
            out.append(arr[left])
            out.append(arr[right])
        left += 1
        right -= 1
    return out
